<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigInnerLabelAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigInnerLabelAccessor trait.
 *
 * Covers null default, string/VO assignment via withInnerLabel,
 * getInnerLabel/innerLabel accessors, and isInnerLabelChanged with/without original.
 */
class TenantConfigInnerLabelAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withInnerLabel creates a new instance with the InnerLabel set
     * from a string value, and getInnerLabel returns the primitive string.
     */
    public function testWithInnerLabelFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigInnerLabelAccessorUnitTest();

        // Act
        $result = $holder->withInnerLabel('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getInnerLabel());
    }
    /**
     * Asserts that withinnerLabel has access to the value object
     * from a string value, and getInnerLabel returns the primitive string.
     */
    public function testWithInnerLabelFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigInnerLabelAccessorUnitTest();

        // Act
        $result = $holder->withInnerLabel('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->innerLabel()->value());
    }
    public function testChangedInnerLabel(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigInnerLabelAccessorUnitTest();
        $original = $holder->withInnerLabel('one');
        $same = $holder->withInnerLabel('one');
        $modified = $holder->withInnerLabel('other');

        // Act
        $unchanged = $holder->isInnerLabelChanged();
        $withSame = $original->isInnerLabelChanged($same);
        $withDiferent = $original->isInnerLabelChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigInnerLabelAccessorUnitTest
{
    use TenantConfigInnerLabelAccessor;
}
